from flask import Flask, request, redirect, jsonify
import html
import checks, ui, db

app = Flask(__name__)

# ---- SQLite: the account and its history are saved in database.db ----
db.run("CREATE TABLE IF NOT EXISTS accounts (id INTEGER PRIMARY KEY, name TEXT, balance REAL DEFAULT 0)")
db.run("CREATE TABLE IF NOT EXISTS transactions (id INTEGER PRIMARY KEY, account_id INTEGER, text TEXT)")
bank = {"account": None, "history": [], "msg": "", "ok": True}
_a = db.rows("SELECT name, balance FROM accounts WHERE id = 1")
if _a:
    _b = _a[0]["balance"]
    bank["account"] = {"name": _a[0]["name"], "balance": int(_b) if float(_b).is_integer() else _b}
    bank["history"] = [r["text"] for r in db.rows("SELECT text FROM transactions WHERE account_id = 1 ORDER BY id")]


def save():
    a = bank["account"]
    ops = [("DELETE FROM accounts", ()), ("DELETE FROM transactions", ())]
    if a is not None:
        ops.append(("INSERT INTO accounts (id, name, balance) VALUES (1, ?, ?)", (str(a.get("name", "")), float(a.get("balance", 0)))))
        ops += [("INSERT INTO transactions (account_id, text) VALUES (1, ?)", (h,)) for h in bank["history"]]
    db.many(ops)


def money(x):
    return ("%.2f" % x).rstrip("0").rstrip(".") if isinstance(x, float) else str(x)


@app.route("/")
def home():
    S = checks.load_all()
    acc = bank["account"]
    msg = '<div class="msg %s">%s</div>' % ("ok" if bank["ok"] else "bad", bank["msg"]) if bank["msg"] else ""

    if acc is None:
        open_form = ('<h2>Open a new account</h2><form method="post" action="/open">' + ui.part(S[2])
                     + ("<button>Open account</button>" if S[3]["status"] == "done" else "") + "</form>"
                     + (ui.box(S[3]) if S[3]["status"] != "done" else ""))
        main = '<div class="card">' + ui.part(S[1]) + msg + open_form + "</div>"
    else:
        shown = dict(acc, name=html.escape(str(acc.get("name", ""))), balance=money(acc.get("balance", 0)))
        btns = ""
        btns += "<button name=\"action\" value=\"deposit\">Deposit</button>" if S[5]["status"] == "done" else ""
        btns += "<button class=\"alt\" name=\"action\" value=\"withdraw\">Withdraw</button>" if S[6]["status"] == "done" else ""
        todo = "".join(ui.box(S[n]) for n in (5, 6) if S[n]["status"] != "done")
        main = ('<div class="card">' + ui.part(S[1]) + "<p>Account holder: <b>%s</b></p>" % shown["name"]
                + ui.part(S[4], shown) + msg
                + '<form method="post" action="/money"><input name="amount" type="number" placeholder="Amount ₹">' + btns + "</form>"
                + todo + "".join(ui.box(S[n]) for n in (7, 8) if S[n]["status"] != "done")
                + ('<form method="post" action="/interest"><button class="amber">Add 4% interest</button></form>' if S[10]["status"] == "done" else ui.box(S[10]))
                + '<p><a href="/close" style="color:#6b7480">Close account (start again)</a></p></div>')
        if S[9]["status"] == "done":
            items = "".join("<li>%s</li>" % html.escape(h) for h in reversed(bank["history"])) or '<li style="color:#6b7480">No transactions yet</li>'
            main += '<div class="card"><h2>History</h2><ul>' + items + "</ul></div>"
        else:
            main += '<div class="card"><h2>History</h2>' + ui.box(S[9]) + "</div>"
    return ui.page("My Bank", S, main)


@app.route("/open", methods=["POST"])
def open_account():
    S = checks.load_all()
    name = request.form.get("name", "").strip() or "Customer"
    if S[3]["status"] == "done":
        bank["account"] = S[3]["f"](name)
        bank["history"], bank["msg"], bank["ok"] = [], "Account opened for %s ✅" % html.escape(name), True
    save()
    return redirect("/")


@app.route("/money", methods=["POST"])
def move_money():
    S = checks.load_all()
    acc = bank["account"]
    action = request.form.get("action", "")
    try:
        amount = float(request.form.get("amount", "0") or 0)
        amount = int(amount) if amount.is_integer() else amount
    except ValueError:
        amount = 0
    if acc is None or action not in ("deposit", "withdraw"):
        return redirect("/")
    if S[8]["status"] == "done" and not S[8]["f"](amount):
        bank["msg"], bank["ok"] = "Enter an amount more than ₹0 ❌", False
    elif action == "withdraw" and S[7]["status"] == "done" and not S[7]["f"](acc, amount):
        bank["msg"], bank["ok"] = "Not enough balance ❌", False
    else:
        step = 5 if action == "deposit" else 6
        if S[step]["status"] == "done":
            S[step]["f"](acc, amount)
            word = "Deposited" if action == "deposit" else "Withdrew"
            bank["msg"], bank["ok"] = "%s ₹%s ✅" % (word, money(amount)), True
            if S[9]["status"] == "done":
                S[9]["f"](bank["history"], "%s ₹%s" % (word, money(amount)))
            save()
    return redirect("/")


@app.route("/interest", methods=["POST"])
def interest():
    S = checks.load_all()
    if bank["account"] is not None and S[10]["status"] == "done":
        S[10]["f"](bank["account"])
        bank["msg"], bank["ok"] = "4% interest added ✅", True
        if S[9]["status"] == "done":
            S[9]["f"](bank["history"], "Interest added (4%)")
        save()
    return redirect("/")


@app.route("/close")
def close():
    bank.update(account=None, history=[], msg="", ok=True)
    save()
    return redirect("/")


# ==============================================================
#  API — ready-made. Call it with curl: commands/08_api_crud.txt
# ==============================================================
def amount_from_body():
    b = request.get_json(silent=True) or request.form
    try:
        return float(b.get("amount", ""))
    except (TypeError, ValueError):
        return None


@app.get("/api/account")
def api_account():                                # SELECT * FROM accounts WHERE id = 1
    a = bank["account"]
    if a is None:
        return jsonify(error="no account yet: open one on the page"), 404
    return jsonify(name=a["name"], balance=a["balance"], history=bank["history"])


@app.post("/api/deposit")
def api_deposit():                                # UPDATE accounts SET balance = balance + ...
    a, amt = bank["account"], amount_from_body()
    if a is None:
        return jsonify(error="no account yet"), 404
    if amt is None or amt <= 0:
        return jsonify(error="amount must be more than 0"), 400
    a["balance"] = a["balance"] + amt
    bank["history"].append("Deposited ₹%s (API)" % money(amt))
    save()
    return jsonify(balance=a["balance"])


@app.post("/api/withdraw")
def api_withdraw():                               # UPDATE accounts SET balance = balance - ...
    a, amt = bank["account"], amount_from_body()
    if a is None:
        return jsonify(error="no account yet"), 404
    if amt is None or amt <= 0:
        return jsonify(error="amount must be more than 0"), 400
    if amt > a["balance"]:
        return jsonify(error="not enough balance"), 400
    a["balance"] = a["balance"] - amt
    bank["history"].append("Withdrew ₹%s (API)" % money(amt))
    save()
    return jsonify(balance=a["balance"])


if __name__ == "__main__":
    print("\n  👉 Open http://localhost:5002 in your browser.  (Stop: Ctrl + C)\n")
    app.run(port=5002)
